SELECT gen.INDX_SNAME AS `指数名称`, mkt.SECCODE AS `指数代码`, mkt.TRADEDATE AS `交易日期`, mkt.CHNG_PCT AS `日涨跌幅(%)` FROM GET_INDX_GEN_INFO gen JOIN INDX_MKT mkt ON gen.INNER_CODE = mkt.INNER_CODE WHERE (gen.INDX_CODE = '000016' OR gen.INDX_SNAME LIKE '%中证白酒%' OR gen.INDX_SNAME LIKE '%中证医疗%') AND gen.USE_STATUS = '使用' AND gen.ISVALID = 1 AND mkt.ISVALID = 1 AND mkt.TRADEDATE = '2026-09-02' AND mkt.CHNG_PCT IS NOT NULL ORDER BY mkt.CHNG_PCT DESC LIMIT 1;
